package live.linghe.privateinput;
import android.app.Instrumentation;import android.os.Bundle;import android.content.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
public final class DocumentHarnessProbe extends Instrumentation {
 private Bundle args;public void onCreate(Bundle data){super.onCreate(data);args=data;start();}
 private void remove(File file){if(file.isDirectory()){File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);}file.delete();}
 public void onStart(){Bundle result=new Bundle();try{Context context=getTargetContext();String id=UUID.fromString(context.getSharedPreferences("document-harness",0).getString("fixture","")).toString();File root=new File(context.getCacheDir(),"lexicon-acceptance-"+id),marker=new File(root,"fixture-owned-v1");if(!new String(Files.readAllBytes(marker.toPath()),StandardCharsets.UTF_8).equals(id))throw new IOException("Unowned fixture");
  PersonalLexicon store=new PersonalLexicon(new File(root,"files/Shared"));PersonalLexicon.Snapshot state=store.load();result.putInt("entries",state.entries.size());result.putBoolean("localEntryPreserved",state.entries.stream().anyMatch(entry->entry.text.equals("本地保留合成")));int exports=0;boolean match=false;File[] docs=new File(root,"documents").listFiles();if(docs!=null)for(File file:docs)if(file.getName().startsWith("out-")&&file.getName().endsWith(".json")){exports++;String encoded=AppFiles.read(file,PersonalLexicon.MAX_BYTES);JSONObject parsed=LosslessJson.object(encoded,PersonalLexicon.MAX_BYTES);if(parsed.has("synchronization"))throw new IOException("Export contains private sync metadata");PersonalLexicon.Snapshot exported=PersonalLexicon.decode(encoded);match=exported.entries.size()==state.entries.size();for(PersonalLexicon.Entry entry:state.entries)if(!exported.entries.stream().anyMatch(item->item.same(entry)))match=false;}
  result.putInt("exports",exports);result.putBoolean("lastExportMatchesVisibleEntries",match);result.putString("fixture",id);
  if("cleanup".equals(args.getString("action"))){remove(root);context.getSharedPreferences("document-harness",0).edit().remove("fixture").commit();context.getSharedPreferences("document-names-"+id,0).edit().clear().commit();if(root.exists())throw new IOException("Fixture cleanup incomplete");result.putBoolean("removed",true);}
  result.putString("result","Passed");result.putBoolean("realUserDataTouched",false);
 }catch(Exception failure){result.putString("result","Failed");result.putString("error",failure.getClass().getSimpleName()+": "+failure.getMessage());}finish("Passed".equals(result.getString("result"))?-1:0,result);}
}
